#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import sys

# Base36 digit set
DIGITS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int) -> str:
    """Convert an integer to a zero-padded 4-character base36 string."""
    if n == 0:
        return '0000'
    result = []
    while n > 0:
        result.append(DIGITS[n % 36])
        n //= 36
    return ''.join(reversed(result)).rjust(4, '0')


def next_order_id(last_id: str) -> str:
    """Given an id like ORD-243G, return the next sequential id."""
    prefix, code = last_id.rsplit('-', 1)
    val = int(code, 36)
    return f'{prefix}-{to_base36(val + 1)}'


def main() -> None:
    with open('ids.txt') as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        print('ORD-0000')
        return
    last = lines[-1]
    print(next_order_id(last))


if __name__ == '__main__':
    main()

