#!/usr/bin/env python3
"""Print the next sequential order id."""

import sys

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 32

CHAR_TO_VAL = {c: i for i, c in enumerate(ALPHABET)}


def decode(s: str) -> int:
    """Convert a 4-char base-32 string (most significant first) to an integer."""
    val = 0
    for ch in s:
        val = val * BASE + CHAR_TO_VAL[ch]
    return val


def encode(n: int) -> str:
    """Convert an integer to a 4-char base-32 string, zero-padded on the left."""
    chars = []
    for _ in range(4):
        chars.append(ALPHABET[n % BASE])
        n //= BASE
    return "".join(reversed(chars))


def main() -> None:
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        # No ids yet – start at all-zeroes
        last_id = ""
    else:
        last_line = lines[-1]
        # Expect format "ORD-XXXX"
        last_id = last_line.removeprefix("ORD-")

    if last_id:
        current_val = decode(last_id)
        next_val = current_val + 1
    else:
        next_val = 0

    next_id = encode(next_val)
    print(f"ORD-{next_id}")


if __name__ == "__main__":
    main()

