"""Generate the next sequential order id."""

import sys

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
ALPHABET_REV = {ch: i for i, ch in enumerate(ALPHABET)}
BASE = len(ALPHABET)  # 32


def to_int(code: str) -> int:
    """Convert a 4-char order code (without ORD- prefix) to integer."""
    n = 0
    for ch in code:
        n = n * BASE + ALPHABET_REV[ch]
    return n


def to_code(n: int) -> str:
    """Convert an integer to a 4-char order code."""
    chars = []
    for _ in range(4):
        chars.append(ALPHABET[n % BASE])
        n //= BASE
    return "".join(reversed(chars))


def main() -> None:
    ids_path = "ids.txt"
    try:
        with open(ids_path) as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        # No ids yet; start at the first code.
        last_code = None
        next_val = 0
    else:
        last_line = lines[-1]
        if not last_line.startswith("ORD-") or len(last_line) != 8:
            print(f"error: invalid id format: {last_line!r}", file=sys.stderr)
            sys.exit(1)
        last_code = last_line[4:]
        next_val = to_int(last_code) + 1

    sys.stdout.write(f"ORD-{to_code(next_val)}\n")


if __name__ == "__main__":
    main()

