#!/usr/bin/env python3
"""Read all .txt files from inbox/ and write a summary report to report.txt."""

import os
import pathlib


def main():
    inbox = pathlib.Path("inbox")
    measurements: list[int] = []

    if inbox.is_dir():
        for txt_file in sorted(inbox.glob("*.txt")):
            with open(txt_file) as f:
                for line in f:
                    line = line.strip()
                    if line:
                        measurements.append(int(line))

    output = pathlib.Path("report.txt")

    if not measurements:
        output.write_text("NO DATA\n")
        return

    total = sum(measurements)
    count = len(measurements)
    average = total / count

    output.write_text(
        f"entries {count}\n"
        f"total {total}\n"
        f"average {average:.2f}\n"
    )


if __name__ == "__main__":
    main()

