#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
OUTPUT = Path(__file__).resolve().parent / "manifest.json"


def sha256_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def build_manifest() -> dict[str, str]:
    manifest: dict[str, str] = {}
    for entry in sorted(RELEASE_DIR.rglob("*")):
        if entry.is_file():
            rel_path = str(entry.relative_to(RELEASE_DIR.parent))
            manifest[rel_path] = sha256_digest(entry)
    return manifest


def main() -> None:
    manifest = build_manifest()
    OUTPUT.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Wrote manifest.json with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

