#!/usr/bin/env python3
"""Generate manifest.json: SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def hex_digest(path: Path) -> str:
    """Return the SHA-256 hex digest of *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    if not RELEASE_DIR.is_dir():
        print(f"error: {RELEASE_DIR} does not exist")
        raise SystemExit(1)

    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if not fpath.is_file():
            continue
        # POSIX relative path with forward slashes (portable manifest key)
        rel = fpath.relative_to(REPO_ROOT).as_posix()
        manifest[rel] = hex_digest(fpath)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"wrote {MANIFEST_PATH} ({len(manifest)} entries)")


if __name__ == "__main__":
    main()

