def fetch(url, transport, sleep=time.sleep):
    """Fetch ``url`` via ``transport`` and return its response text.

    Retries up to 8 times when transport raises TransportError, sleeping
    between each attempt. The last TransportError propagates if all attempts
    fail.
    """
    max_attempts = 8
    for attempt in range(max_attempts):
        try:
            return transport(url)
        except TransportError:
            if attempt == max_attempts - 1:
                raise
            sleep(1)
    # unreachable
    return None

