import time


class TransportError(Exception):
    """Raised by a transport when a fetch attempt fails."""


def fetch(url, transport, sleep=time.sleep):
    """Fetch ``url`` via ``transport`` and return its response text.

    Retries up to 8 total attempts on TransportError using exponential
    backoff starting at 1 s, doubling per attempt, capped at 30 s, with
    uniform jitter applied to every delay.
    """
    max_attempts = 8
    base_delay = 1.0
    cap = 30.0

    for attempt in range(max_attempts):
        try:
            return transport(url)
        except TransportError:
            if attempt == max_attempts - 1:
                raise
            delay = min(base_delay * (2 ** attempt), cap)
            jitter = random.uniform(0, delay)
            sleep(jitter)

